    aligned_input_buffer = malloc(data_num_bytes);
    true ? (void)0 : ::logging::VoidifyStream(!(IsAligned(aligned_input_buffer))) & (*::logging::g_swallow_stream);
    memcpy(aligned_input_buffer, data, data_num_bytes);
