template <typename Consumer>
bool ParseFormatString(string_view src, Consumer consumer) {
  int next_arg = 0;
  const char* p = src.data();
  const char* const end = p + src.size();
  while (p != end) {
    const char* percent =
        static_cast<const char*>(memchr(p, '%', static_cast<size_t>(end - p)));
    if (!percent) {

      return consumer.Append(string_view(p, static_cast<size_t>(end - p)));
    }

    if ((__builtin_expect(false || (!consumer.Append( string_view(p, static_cast<size_t>(percent - p)))), false))) {

      return false;
    }
    if ((__builtin_expect(false || (percent + 1 >= end), false))) return false;

    auto tag = GetTagForChar(percent[1]);
    if (tag.is_conv()) {
      if ((__builtin_expect(false || (next_arg < 0), false))) {




        return false;
      }
      p = percent + 2;




      UnboundConversion conv;
      conv.conv = tag.as_conv();
      conv.arg_position = ++next_arg;
      if ((__builtin_expect(false || (!consumer.ConvertOne(conv, string_view(percent + 1, 1))), false))) {

        return false;
      }
    } else if (percent[1] != '%') {
      UnboundConversion conv;
      p = ConsumeUnboundConversionNoInline(percent + 1, end, &conv, &next_arg);
      if ((__builtin_expect(false || (p == nullptr), false))) return false;
      if ((__builtin_expect(false || (!consumer.ConvertOne( conv, string_view(percent + 1, static_cast<size_t>(p - (percent + 1))))), false))) {


        return false;
      }
    } else {
      if ((__builtin_expect(false || (!consumer.Append("%")), false))) return false;
      p = percent + 2;
      continue;
    }
  }
  return true;
}



