template <typename T, typename U>
struct TraceTrait<std::pair<T, U>> {
  TraceTrait() = delete; TraceTrait(const TraceTrait&) = delete; TraceTrait& operator=(const TraceTrait&) = delete; void* operator new(size_t) = delete; void* operator new(size_t, WTF::NotNullTag, void*) = delete; void* operator new(size_t, void*) = delete;

 public:
  static TraceDescriptor GetTraceDescriptor(const void* self) {



    (true) ? ::logging::NotReachedFailure() : true ? (void)0 : ::logging::VoidifyStream() & (*::logging::g_swallow_stream);
  }

  static void Trace(Visitor* visitor, const std::pair<T, U>* pair) {
    blink::TraceIfNeeded<U>::Trace(visitor, pair->second);
    blink::TraceIfNeeded<T>::Trace(visitor, pair->first);
  }
};

